SELECT R.RULE_ID, R.RULE_CONTENT,
/* 준수 거래 수 */ SUM( CASE WHEN RC.FOLLOWED = 'Y' THEN 1 ELSE 0 END ) AS FOLLOWED_TRADE_COUNT,
/* 준수 거래 평균 수익률 */ NVL( AVG( CASE WHEN RC.FOLLOWED = 'Y' THEN (T.SELL_PRICE - T.BUY_PRICE) / T.BUY_PRICE * 100 END ), 0 ) AS FOLLOWED_AVERAGE_RETURN_RATE,
/* 준수 거래 총 실현손익 */ NVL( SUM( CASE WHEN RC.FOLLOWED = 'Y' THEN (T.SELL_PRICE - T.BUY_PRICE) * T.QUANTITY ELSE 0 END ), 0 ) AS FOLLOWED_TOTAL_PROFIT,
/* 미준수 거래 수 */ SUM( CASE WHEN RC.FOLLOWED = 'N' THEN 1 ELSE 0 END ) AS NOT_FOLLOWED_TRADE_COUNT,
/* 미준수 거래 평균 수익률 */ NVL( AVG( CASE WHEN RC.FOLLOWED = 'N' THEN (T.SELL_PRICE - T.BUY_PRICE) / T.BUY_PRICE * 100 END ), 0 ) AS NOT_FOLLOWED_AVERAGE_RETURN_RATE,
/* 미준수 거래 총 실현손익 */ NVL( SUM( CASE WHEN RC.FOLLOWED = 'N' THEN (T.SELL_PRICE - T.BUY_PRICE) * T.QUANTITY ELSE 0 END ), 0 ) AS NOT_FOLLOWED_TOTAL_PROFIT
FROM TRADE_RULE R
LEFT JOIN TRADE_RULE_CHECK RC ON R.RULE_ID = RC.RULE_ID
LEFT JOIN TRADE T ON RC.TRADE_ID = T.TRADE_ID
WHERE R.MEMBER_ID = #{memberId}
GROUP BY R.RULE_ID, R.RULE_CONTENT
ORDER BY R.RULE_ID


SELECT COUNT(*)
FROM TRADE_RULE
WHERE RULE_ID = #{ruleId}
  AND MEMBER_ID = #{memberId}
